<template><div class="page"><h2 class="page-title">计划版本历史</h2><p class="muted">历史方案只读，不会被新计划覆盖。</p><el-timeline v-if="plans.length" class="section"><el-timeline-item v-for="p in plans" :key="p.id" :timestamp="p.created_at" :type="p.is_current?'success':'info'"><el-card><div class="actions"><b>Plan v{{p.version}}</b><el-tag>{{p.status}}</el-tag><el-tag v-if="p.risk_level" type="warning">{{p.risk_level}} · 情景风险</el-tag></div><p>预计期末存款：{{formatMoney(p.expected_final_savings_minor)}} · 父计划：{{p.parent_plan_id?`v${parentVersion(p.parent_plan_id)}`:'初始计划'}}</p><el-button text @click="open(p.id)">查看当时方案</el-button></el-card></el-timeline-item></el-timeline><EmptyGuide v-else description="还没有预算计划" action="/budgets"/><el-drawer v-model="visible" title="历史方案详情" size="55%"><el-table :data="detail.items"><el-table-column prop="week_start" label="周"/><el-table-column prop="category_name" label="类别"/><el-table-column label="自然消费"><template #default="s">{{formatMoney(s.row.natural_spend_minor)}}</template></el-table-column><el-table-column label="推荐预算"><template #default="s">{{formatMoney(s.row.recommended_budget_minor)}}</template></el-table-column></el-table></el-drawer></div></template>
<script setup>
import { onMounted,ref } from 'vue';import { api } from '../api/client.js';import { formatMoney } from '../utils/money.js';import EmptyGuide from '../components/EmptyGuide.vue'
const plans=ref([]),visible=ref(false),detail=ref({items:[]});onMounted(async()=>plans.value=(await api.get('/budgets')).items)
function parentVersion(id){return plans.value.find(x=>x.id===id)?.version||'?'}async function open(id){detail.value=await api.get(`/budgets/${id}`);visible.value=true}
</script>
